values
  ('3c07a334-67f7-575b-b8a9-65023c5c5471',(select organizer_id from public.event_sources where slug='karabas'),'Тіна Кароль «Кохання. Сльози. Маніфест»','Запрошуємо на грандіозний концерт до 20-річчя творчого шляху однієї з найуспішніших українських співачок – Тіни Кароль. Не пропустіть це масштабне шоу, наповнене теплими спогадами, справжніми…','music','Київ','Київський Палац спорту, пл. Спортивна, 1, Київ',50.4371798,30.5223566,'2026-09-19T21:00:00+03:00','2026-09-20T00:00:00+03:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019d0af9-76f7-7f20-8628-cba5894e3783/2772696093_ImageBig639225904139289745.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/tina-karol-kokhannya-sl-ozy-manifest/','https://kyiv.karabas.com/tina-karol-kokhannya-sl-ozy-manifest/','2026-09-19:50.44,30.52',0.85,'live',1790.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('a423dfec-6973-5984-bda1-a4c72c4a3b87',(select organizer_id from public.event_sources where slug='karabas'),'Jerry Heil','Незрівнянна Jerry Heil запрошує всіх на концерт із фантастичною програмою “Jerelo” на біс! Це буде незабутня музична подорож із шаленою енергетикою, улюбленими піснями та веселими танцями. Приходьте…','music','Київ','Київський Палац спорту, пл. Спортивна, 1, Київ',50.4371798,30.5223566,'2026-12-12T20:00:00+02:00','2026-12-13T00:00:00+02:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019efc7f-a449-7965-a9b2-b65f208e64b1/2818902772_ImageBig639179278501389997.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/jerry-heil-kyiv/','https://kyiv.karabas.com/jerry-heil-kyiv/','2026-12-12:50.44,30.52',0.85,'live',990.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('5ede2ce0-4426-5d0f-a155-58236394342d',(select organizer_id from public.event_sources where slug='karabas'),'Мій Music Hall','Запрошуємо на головну музичну подію цієї осені! Грандіозний концерт “Мій Music Hall” знов збере на одній сцені найяскравіших українських зірок і здивує дивовижними номерами. Таке фантастичне шоу…','music','Київ','Національний палац мистецтв «Україна», вул. В. Васильківська, 103, Київ',50.4222048,30.5211548,'2026-11-07T19:00:00+02:00','2026-11-08T00:00:00+02:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019d9c75-4d47-79bc-94b2-ee7f8e3555fb/2797680884_ImageBig639241389587187578.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/miy-music-hall-2/','https://kyiv.karabas.com/miy-music-hall-2/','2026-11-07:50.42,30.52',0.934,'live',500.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('62b55001-f1d0-511d-9c98-e4254138831f',(select organizer_id from public.event_sources where slug='karabas'),'Анна Трінчер','Запрошуємо на перший концерт однієї з найяскравіших зірок української поп-сцени Анни Трінчер у київському Палаці спорту. Виступ стане наймасштабнішою подією в кар’єрі артистки та розпочне новий…','music','Київ','Київський Палац спорту, пл. Спортивна, 1, Київ',50.4371798,30.5223566,'2026-11-20T21:00:00+02:00','2026-11-21T00:00:00+02:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019e3a62-c508-729f-8916-8d1201a9eab2/2678176684_ImageBig639147903079576290.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/anna-trincher-65/','https://kyiv.karabas.com/anna-trincher-65/','2026-11-20:50.44,30.52',0.85,'live',690.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('7a46b150-0fed-52da-9829-2a9eebfccc8c',(select organizer_id from public.event_sources where slug='karabas'),'ДахаБраха','Запрошуємо на концерт автентичного та популярного квартету “ДахаБраха”. Це один із найвідоміших у світі українських гуртів, який грає неповторний етно-хаус і чиї live-show завжди відбуваються з…','music','Київ','Місце проведення: МЦКМ, Алея Героїв Небесної Сотні, 1, Київ',50.4498664,30.5278357,'2026-10-18T21:00:00+03:00','2026-10-19T00:00:00+03:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019e8dc8-e54a-7625-a999-c64ac7dcdf42/2832724806_ImageBig639160164791258612.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/dakhabrakha-20/','https://kyiv.karabas.com/dakhabrakha-20/','2026-10-18:50.45,30.53',0.934,'live',490.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('1f0c4450-0047-5d40-b963-98671a5fd815',(select organizer_id from public.event_sources where slug='karabas'),'KLER','Запрошуємо на концерт найтанцювальнішої співачки KLER! На вас чекають улюблені пісні, цікаві прем''єри, фантастична атмосфера та безліч приємних спогадів. Станьте частиною цього незабутнього великого…','music','Київ','Stereo Plaza, Лобановського пр-т, 119, Київ',50.4082862,30.5130017,'2026-12-18T21:00:00+02:00','2026-12-19T00:00:00+02:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/01a047f4-af47-7cc6-8ef1-83df2b598031/2845124429_ImageBig639231922516137850.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/kler-15/','https://kyiv.karabas.com/kler-15/','2026-12-18:50.41,30.51',0.91,'live',890.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
