  ('d9095b80-5ac0-5106-8cf3-c29b719e0ded',(select organizer_id from public.event_sources where slug='karabas'),'Наталія Могилевська','Запрошуємо на великий весняний концерт легендарної Наталії Могилевської! Неперевершена, талановита та граціозна артистка підготувала нове ексклюзивне шоу з найкращими піснями, яскравими номерами та…','music','Київ','Київський Палац спорту, пл. Спортивна, 1, Київ',50.4371798,30.5223566,'2027-03-07T20:00:00+02:00','2027-03-08T00:00:00+02:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019ff583-5abb-7056-9858-0f25d859dfcd/2865345796_ImageBig639221375705066657.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/nataliya-mohylevs-ka-35/','https://kyiv.karabas.com/nataliya-mohylevs-ka-35/','2027-03-07:50.44,30.52',0.85,'live',390.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('6fa54c95-bc33-5c6c-8da7-217155afbfe1',(select organizer_id from public.event_sources where slug='karabas'),'Дизель Шоу. До Дня Козацтва','Запрошуємо на грандіозний концерт “До Дня Козацтва” від неперевершених “Дизель Шоу” . На вас чекає абсолютно нова програма з блискучими жартами, життєвими номерами, цікавими персонажами та яскравими…','music','Київ','Місце проведення: МЦКМ, Алея Героїв Небесної Сотні, 1, Київ',50.4498664,30.5278357,'2026-10-11T21:00:00+03:00','2026-10-12T00:00:00+03:00','Europe/Kyiv',1,'https://images.karabas.com/external/018e50bb-71e5-7428-9b44-4f503fcfd169/events/019ffa22-d287-712f-ae4f-733af528abbf/2871237862_ImageBig639222154199239217.jpeg','import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/dyzel-shou-do-dnya-kozatstva-8/','https://kyiv.karabas.com/dyzel-shou-do-dnya-kozatstva-8/','2026-10-11:50.45,30.53',0.934,'live',300.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
  ('9df57b13-80a8-53bf-b351-f9d638f27688',(select organizer_id from public.event_sources where slug='karabas'),'Шлягер року','Запрошуємо на грандіозний гала-концерт музичної премії “Шлягер року” у Палаці “Україна”. Цього вечора на сцені зберуться найкращі виконавці української естради з улюбленими хітами. Таку подію не…','music','Київ','Національний палац мистецтв «Україна», вул. В. Васильківська, 103, Київ',50.4222048,30.5211548,'2026-11-04T20:00:00+02:00','2026-11-05T00:00:00+02:00','Europe/Kyiv',1,null,'import',(select id from public.event_sources where slug='karabas'),'https://kyiv.karabas.com/shlyaher-roku-2/','https://kyiv.karabas.com/shlyaher-roku-2/','2026-11-04:50.42,30.52',0.834,'live',350.0,false,'0bf832e1-90eb-4881-942d-3e9f1e0c3070'),
