on conflict (source_id,source_uid) where source_id is not null do update set
  title=excluded.title, description=excluded.description, category=excluded.category,
  city=excluded.city, address=excluded.address,
  latitude=excluded.latitude, longitude=excluded.longitude,
  starts_at=excluded.starts_at, ends_at=excluded.ends_at,
  image_url=excluded.image_url, canonical_url=excluded.canonical_url,
  dedupe_key=excluded.dedupe_key, quality=excluded.quality,
  import_status='live', price_min=excluded.price_min, is_free=excluded.is_free,
  ingest_run_id=excluded.ingest_run_id, updated_at=now();
update public.events set import_status='withdrawn', updated_at=now()
where source_id=(select id from public.event_sources where slug='concert_ua')
  and import_status='live' and ingest_run_id is distinct from '0bf832e1-90eb-4881-942d-3e9f1e0c3070'
  and starts_at > now();
